INSERT INTO `pengumpulan_tugas` VALUES (2, 745, 3, 'tes12313123', 'https://localhost/api-edulite/media/507d38d8aa13b402fa95182be8b40d7e.PNG', 0);
INSERT INTO `pengumpulan_tugas` VALUES (3, 754, 6, 'Produksi massal adalah cara pabrik membuat barang/makanan/minuman dengan ceoat dan banyak,agar semua orang bisa mendapatkan dengan harga murah', 'https://localhost/api-edulite/media/246cd06e2427f30149e814aae46cf1d9.png', 0);
INSERT INTO `pengumpulan_tugas` VALUES (4, 753, 6, 'Produksi Masal adalah sistem produksi barang dalam jumlah besar yang dilakukan secara berkelanjutan dengan mengikuti standar yang telah ditentukan untuk memenuhi permintaan pasar. \r\nCiri-ciri Produksi Masal:\r\nJumlah produksi besar: Tujuan utama adalah men', 'https://localhost/api-edulite/media/c6aac1a851b20e50ccc40417f54f2ed7.png', 0);
INSERT INTO `pengumpulan_tugas` VALUES (5, 753, 6, 'Produksi Masal adalah sistem produksi barang dalam jumlah besar yang dilakukan secara berkelanjutan dengan mengikuti standar yang telah ditentukan untuk memenuhi permintaan pasar. \r\nCiri-ciri Produksi Masal:\r\nJumlah produksi besar: Tujuan utama adalah men', 'https://localhost/api-edulite/media/fc91411318be73086b19bb9d671e40d2.png', 0);
INSERT INTO `pengumpulan_tugas` VALUES (6, 991, 4, '1. Mainboard\r\n2. Processor (CPU)\r\n3. Harddisk (HDD)\r\n4. Solid State Drive (SSD)\r\n5. Random Access Memory (RAM)\r\n6. Optical Drive (CD/DVD)\r\n7. Floppy Disk\r\n8. VGA Card (Kartu Grafis)\r\n9. Sound Card\r\n10. Keyboard\r\n11.Mouse\r\n12. Monitor\r\n13. Printer', 'https://localhost/api-edulite/media/925bcbd8db1eb112ff12dbae3e7e4424.docx', 0);
INSERT INTO `pengumpulan_tugas` VALUES (7, 991, 7, 'Pengenalan isu, Rangkaian argumentasi, Penegasan kembali. ', 'https://localhost/api-edulite/media/e57ba84ae43fd1d16328011d53bdd6e6.docx', 0);
