INSERT INTO `pengumpulan_tugas` VALUES (12, 902, 5, '', 'https://localhost/api-edulite/media/d02cce0d1df8e1c27d4d76845b102aa3.docx', 0);
INSERT INTO `pengumpulan_tugas` VALUES (13, 777, 6, 'Produksi massal, juga dikenal sebagai aliran produksi atau produksi terus-menerus, adalah sistem produksi dalam jumlah besar dari produk yang standar, termasuk dan terutama pada jalur perakitan. Bersama-sama dengan pekerjaan produksi dan produksi tumpak, ', '', 0);
INSERT INTO `pengumpulan_tugas` VALUES (14, 771, 6, 'Produksi massal adalah proses pembuatan produk dalam jumlah besar yang menggunakan jalur perakitan atau teknologi otomasi. Produksi massal juga dikenal sebagai produksi aliran, produksi seri, atau produksi serial. \r\nBerikut beberapa ciri-ciri produksi mas', 'https://localhost/api-edulite/media/8fd290193bbc23e96dfb0914f7db2b49.png', 0);
