INSERT INTO `prakerin_jurnal_harian` VALUES (40, 810, '2024-01-22', 'pada hari sabtu tgl 20-01-24,kami mempelajari bab jaringan singkat lalu dgn praktek di cisco tracer,sangat senang namun merumitkan jika terjadi kesalahan...hehe...', 0, '2024-01-22 14:24:34');
INSERT INTO `prakerin_jurnal_harian` VALUES (41, 810, '2024-01-22', 'hari ini senin 22-01-24,disiang yg cerah nan menyejukan,kami dibimbing pak rendy mengenal apa itu pemprograman melalui online c++,sangat banyak contoh dan materi yg diterangkan beliau,lalu jika sdh paham kami diberi tugas membuat contoh rumus luas lingkaran.terima kasih....', 0, '2024-01-22 14:40:19');
INSERT INTO `prakerin_jurnal_harian` VALUES (42, 810, '2024-01-22', 'dan alhamdulillah berhasil dong hehe....google banyak hehe...', 0, '2024-01-22 14:40:59');
