INSERT INTO `prakerin_jurnal_harian` VALUES (44, 810, '2024-01-24', 'hari ini 23-01-24 jam kosong,wifi macet,tak ada pembekalan,jadi saya memutuskan turun ke lantai satu untuk mencari jaringan,alhamdulilah dapet,lalu saya melihat2 halaman website untuk contoh ', 0, '2024-01-24 13:57:12');
