INSERT INTO `prakerin_jurnal_harian` VALUES (46, 810, '2024-01-24', 'hari ini 24-01-24,cuaca yg mendung setelah panas berlalu,kami diberi tugas masing-masing oleh pak avi.klo saya mengubah layout websmpitasysyadzili.org', 0, '2024-01-24 13:58:58');
