amin` AS `jenis_kelamin`,`siswa`.`saldo` AS `saldo`,`siswa`.`is_alumni` AS `is_alumni`,`siswa`.`iddepartment_fk` AS `iddepartment_fk`,`prakerin_kelompok`.`nama_kelompok` AS `nama_kelompok`,`prakerin_kelompok`.`id_prakerin_kelompok` AS `id_prakerin_kelompok` from ((`prakerin_siswa` join `prakerin_kelompok` on(`prakerin_siswa`.`idprakerinkelompok_fk` = `prakerin_kelompok`.`id_prakerin_kelompok`)) join `siswa` on(`prakerin_siswa`.`idsiswa_fk` = `siswa`.`id_siswa`)) ;

