`id_jurusan`,`jurusan`.`jurusan` AS `jurusan`,`jurusan`.`singkatan` AS `singkatan`,(select `tingkat`.`tingkat` from `tingkat` where `tingkat`.`id_tingkat` = `kelas`.`idtingkat_fk`) AS `nama_tingkat` from ((`siswa` join `kelas` on(`kelas`.`id_kelas` = `siswa`.`idkelas_fk`)) join `jurusan` on(`jurusan`.`id_jurusan` = `siswa`.`idjurusan_fk`)) ;

-- ----------------------------
-- View structure for v_tanggungan_siswa
-- ----------------------------
DROP VIEW IF EXISTS `v_tanggungan_siswa`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `v_tanggungan_siswa` AS SELECT
	tanggungan_siswa.id_tanggungan_siswa AS id_tanggungan_siswa, 
	tanggungan_siswa.idsiswa_fk AS idsiswa_fk, 
	tanggungan_siswa.idjenispenerimaan_fk AS idjenispenerimaan_fk, 
	tanggungan_siswa.jumlah AS jumlah, 
	jenis_penerimaan.id_jenis_penerimaan AS id_jenis_penerimaan, 
	jenis_penerimaan.nama AS nama, 
	jenis_penerimaan.kas AS kas, 
	jenis_penerimaan.pendapatan AS pendapatan, 
	jenis_penerimaan.piutang AS piutang, 
	jenis_penerimaan.diskon AS diskon, 
	jenis_penerimaan.is_edit AS is_edit, 
	jenis_penerimaan.bulanan AS bulanan, 
	jenis_penerimaan.template_nota AS template_nota, 
	tanggungan_siswa.periode_awal, 
	tanggungan_siswa.periode_akhir, 
	jenis_penerimaan.idtahunajaran_fk,
  PERIOD_DIFF(REPLACE(periode_akhir, '-', ''), REPLACE(periode_awal, '-', '')) + 1 AS jumlah_bulan
FROM
	(
		tanggungan_siswa
		join
		jenis_penerimaan
		ON 
			(
				tanggungan_siswa.idjenispenerimaan_fk = jenis_penerimaan.id_jenis_penerimaan
			)
	) ;

